'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { api } from '@/lib/api';
import { useAuth } from '@/contexts/AuthContext';
import { ShoppingCart, CalendarDays, Star, Gift } from 'lucide-react';
import Link from 'next/link';

const UserHome = () => {
  const { user } = useAuth();
  const [loyaltyPoints, setLoyaltyPoints] = useState(0);
  const [recentOrders, setRecentOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        // Fetch loyalty points
        const loyaltyRes = await api.get(`/loyalty/${user?._id}`);
        setLoyaltyPoints(loyaltyRes.data.points || 0);

        // Fetch recent orders
        const ordersRes = await api.get(`/orders?user=${user?._id}&limit=3`);
        setRecentOrders(ordersRes.data.data || []);
      } catch (error) {
        console.error('Error fetching user data:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchUserData();
    }
  }, [user]);

  if (loading) {
    return <div className="flex justify-center items-center min-h-screen">Đang tải...</div>;
  }

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">
          Xin chào, {user?.name}!
        </h1>
        <p className="text-gray-600">Chào mừng bạn đến với nhà hàng của chúng tôi</p>
      </div>

      {/* User Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Điểm tích lũy</CardTitle>
            <Star className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-yellow-600">{loyaltyPoints}</div>
            <p className="text-xs text-muted-foreground">điểm</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Đơn hàng gần đây</CardTitle>
            <ShoppingCart className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{recentOrders.length}</div>
            <p className="text-xs text-muted-foreground">đơn hàng</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Thành viên</CardTitle>
            <Gift className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{user?.isMember ? '✓' : '✗'}</div>
            <p className="text-xs text-muted-foreground">
              {user?.isMember ? 'VIP' : 'Thường'}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Ưu đãi</CardTitle>
            <CalendarDays className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">5</div>
            <p className="text-xs text-muted-foreground">ưu đãi có sẵn</p>
          </CardContent>
        </Card>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
        <Card>
          <CardHeader>
            <CardTitle>Xem Menu</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Khám phá các món ăn ngon của chúng tôi</p>
            <Link href="/menu">
              <Button className="w-full">Xem Menu</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Đặt bàn</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Đặt bàn trước để có trải nghiệm tốt nhất</p>
            <Link href="/reservations/create">
              <Button className="w-full">Đặt bàn ngay</Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Lịch sử đơn hàng</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-4">Xem các đơn hàng đã đặt trước đó</p>
            <Link href="/orders">
              <Button className="w-full" variant="outline">Xem lịch sử</Button>
            </Link>
          </CardContent>
        </Card>
      </div>

      {/* Recent Orders */}
      {recentOrders.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Đơn hàng gần đây</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {recentOrders.map((order: any) => (
                <div key={order._id} className="flex justify-between items-center p-4 border rounded-lg">
                  <div>
                    <p className="font-medium">Đơn hàng #{order._id.slice(-6)}</p>
                    <p className="text-sm text-gray-600">
                      {new Date(order.createdAt).toLocaleDateString('vi-VN')}
                    </p>
                    <p className="text-sm">Trạng thái: {order.status}</p>
                  </div>
                  <div className="text-right">
                    <p className="font-bold">{order.totalPrice?.toLocaleString('vi-VN')} VND</p>
                    <Button size="sm" variant="outline">
                      Xem chi tiết
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default UserHome;
