'use client';

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { QrCode, ShoppingCart, CalendarDays, Users } from 'lucide-react';
import Link from 'next/link';

const GuestHome = () => {
  return (
    <div className="container mx-auto py-8 px-4">
      {/* Hero Section */}
      <div className="text-center mb-12">
        <h1 className="text-4xl md:text-6xl font-bold text-gray-900 mb-4">
          Chào mừng đến với nhà hàng
        </h1>
        <p className="text-xl text-gray-600 mb-8 max-w-2xl mx-auto">
          Trải nghiệm ẩm thực tuyệt vời với hương vị truyền thống và phục vụ hiện đại
        </p>
        <div className="flex flex-col sm:flex-row gap-4 justify-center">
          <Link href="/auth/login">
            <Button size="lg" className="w-full sm:w-auto">
              Đăng nhập
            </Button>
          </Link>
          <Link href="/auth/register">
            <Button size="lg" variant="outline" className="w-full sm:w-auto">
              Đăng ký tài khoản
            </Button>
          </Link>
        </div>
      </div>

      {/* Features */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
        <Card className="text-center">
          <CardHeader>
            <div className="mx-auto w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center mb-4">
              <QrCode className="h-6 w-6 text-orange-600" />
            </div>
            <CardTitle className="text-lg">Quét QR để order</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600">Quét mã QR trên bàn để đặt món nhanh chóng</p>
          </CardContent>
        </Card>

        <Card className="text-center">
          <CardHeader>
            <div className="mx-auto w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center mb-4">
              <ShoppingCart className="h-6 w-6 text-blue-600" />
            </div>
            <CardTitle className="text-lg">Menu đa dạng</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600">Hơn 100 món ăn từ truyền thống đến hiện đại</p>
          </CardContent>
        </Card>

        <Card className="text-center">
          <CardHeader>
            <div className="mx-auto w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <CalendarDays className="h-6 w-6 text-green-600" />
            </div>
            <CardTitle className="text-lg">Đặt bàn online</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600">Đặt bàn trước để đảm bảo có chỗ ngồi</p>
          </CardContent>
        </Card>

        <Card className="text-center">
          <CardHeader>
            <div className="mx-auto w-12 h-12 bg-purple-100 rounded-full flex items-center justify-center mb-4">
              <Users className="h-6 w-6 text-purple-600" />
            </div>
            <CardTitle className="text-lg">Phục vụ tận tình</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600">Đội ngũ nhân viên chuyên nghiệp và thân thiện</p>
          </CardContent>
        </Card>
      </div>

      {/* Actions for Guests */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Quét QR để đặt món</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-6">
              Bạn đang ngồi tại bàn? Quét mã QR trên bàn để xem menu và đặt món ngay lập tức
              mà không cần tạo tài khoản.
            </p>
            <Link href="/guest/scan">
              <Button className="w-full" size="lg">
                <QrCode className="h-5 w-5 mr-2" />
                Quét QR Code
              </Button>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Tạo tài khoản để nhận ưu đãi</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-gray-600 mb-6">
              Đăng ký thành viên để tích điểm, nhận ưu đãi đặc biệt và quản lý lịch sử
              đơn hàng của bạn.
            </p>
            <div className="space-y-3">
              <div className="flex items-center text-sm text-gray-600">
                <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                Tích điểm với mỗi đơn hàng
              </div>
              <div className="flex items-center text-sm text-gray-600">
                <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                Ưu đãi đặc biệt cho thành viên
              </div>
              <div className="flex items-center text-sm text-gray-600">
                <div className="w-2 h-2 bg-green-500 rounded-full mr-3"></div>
                Đặt bàn online dễ dàng
              </div>
            </div>
            <Link href="/auth/register">
              <Button className="w-full mt-6" variant="outline" size="lg">
                Đăng ký ngay
              </Button>
            </Link>
          </CardContent>
        </Card>
      </div>

      {/* Restaurant Info */}
      <div className="bg-gray-50 rounded-lg p-8 text-center">
        <h2 className="text-2xl font-bold text-gray-900 mb-4">
          Thông tin liên hệ
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div>
            <h3 className="font-semibold mb-2">Địa chỉ</h3>
            <p className="text-gray-600">123 Đường ABC, Quận XYZ, TP.HCM</p>
          </div>
          <div>
            <h3 className="font-semibold mb-2">Điện thoại</h3>
            <p className="text-gray-600">(028) 1234 5678</p>
          </div>
          <div>
            <h3 className="font-semibold mb-2">Giờ mở cửa</h3>
            <p className="text-gray-600">Thứ 2 - Chủ nhật: 10:00 - 22:00</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GuestHome;
